    "p_testable": 0.25,
    "blocking_constraints": [
      {
        "code": "MEASURE_RELIABILITY",
        "text": "The H2-H1 difference in opponent scoring may be dominated by random game-to-game variance, leaving little reliable between-team signal. Prior player-level metrics show ICC ≤ 0.22."
